code_snippets.parse_list:
def parse(self, response):
    items = response.css('ul li')
    for item in items:
        title = item.css('strong::text, a::text, span::text').get(default='').strip()
        pdf_url = item.css('a[href$=".pdf"]::attr(href)').get()
        yield {
            'title': title,
            'pdf_url': response.urljoin(pdf_url) if pdf_url else None
        }
